IF (SELECT COUNT(*) FROM sys.tables WHERE schema_id=SCHEMA_ID('dbo') AND name IN('notification_operation_reservations','notification_publications','notification_delivery_intents','fe04_cleaner_attributions'))<>4 THROW 51990,'Closure table missing',1;
IF (SELECT COUNT(*) FROM sys.triggers WHERE name IN('TR_fs009_publication_immutable','TR_fs009_operation_immutable','TR_dev3_closure_publication_source','TR_fe04_cleaner_immutable') AND is_disabled=0)<>4 THROW 51990,'Closure guard missing',1;
IF (SELECT COUNT(*) FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.notification_publications') AND name IN('UX_fs009_publication_operation','UX_fs015_assignment_publication','UX_fs015_occurrence') AND is_unique=1 AND is_disabled=0)<>3 THROW 51990,'Outbox deduplication missing',1;
IF COL_LENGTH('dbo.notification_publications','occurrence_key')<>120 OR OBJECT_ID('dbo.fe04_capture_cleaner_attribution','P') IS NULL THROW 51990,'Closure contract missing',1;
IF NOT EXISTS(SELECT 1 FROM sys.database_permissions WHERE major_id=OBJECT_ID('dbo.fe04_cleaner_attributions') AND grantee_principal_id=DATABASE_PRINCIPAL_ID('public') AND permission_name='INSERT' AND state='D') THROW 51990,'Attribution writer boundary missing',1;